/// A codec of the shape `SisSession` asks for.
///
/// It does not serialise anything realistic — CDR is FastCDR's job and testing
/// it would test FastCDR. It writes a recognisable marker so a test can assert
/// that the bytes on the wire came from the request it was given, and it can be
/// told to fail so the encode/decode error paths are exercised.
struct StubCodec
{
    static bool encode_fails;
    static bool decode_fails;
    static std::string last_decoded_marker;

    template <class T>
    static Result<void> encode(const T&, std::vector<std::uint8_t>& out)
    {
        if (encode_fails) { return Result<void>::fail(Error::EncodeFailed); }
        const char* marker = "STUB";
        out.assign(marker, marker + 4);
        return Result<void>::ok();
    }

    template <class T>
    static Result<void> decode(BytesView b, T& out)
    {
        if (decode_fails) { return Result<void>::fail(Error::DecodeFailed); }
        if constexpr (has_stub_decode<T>::value)
        {
            if (!out.stub_decode(b)) { return Result<void>::fail(Error::DecodeFailed); }
        }
        else
        {
            (void)b;
            (void)out;
        }
        return Result<void>::ok();
    }

private:
    template <class T, class = void>
    struct has_stub_decode : std::false_type {};
    template <class T>
    struct has_stub_decode<T, std::void_t<decltype(std::declval<T&>().stub_decode(std::declval<BytesView>()))>>
        : std::true_type {};
};

inline bool StubCodec::encode_fails = false;
inline bool StubCodec::decode_fails = false;
inline std::string StubCodec::last_decoded_marker;

/// Builds an OK reply the way the engine would: a handle exactly when the
/// state carries one, its topics the engine's choice. They are deliberately
/// *not* `{handle}/status`: nothing in this library may compose them.
inline ::sqe_msgs::rpc::SISRelationStreamReply make_reply(RelationState state, const char* handle)
{
    ::sqe_msgs::rpc::SISRelationStreamReply r;
    r.header_.status_ = ::sqe_msgs::rpc::SIS_STATUS_OK;
    r.header_.engine_id_ = "eng";
    r.header_.engine_epoch_ = 1;
    r.relation_.state_ = static_cast<::sqe_msgs::rpc::SISRelationState>(state);
    if (carries_handle(state))
    {
        ::sqe_msgs::rpc::SISStreamHandle h;
        h.handle_ = handle;
        h.data_topic_ = handle;
        h.status_topic_ = std::string(handle) + "/st";
        h.plan_topic_ = std::string(handle) + "/pl";
        r.handle_.set(h);
    }
    return r;
}

/// A `Handle`, obtained the only way there is: from a reply.
inline Handle handle_for(const char* handle)
{
    return Handle::from_reply(make_reply(RelationState::Active, handle)).value();
}

